-- Phase 2A audited schema. Do not apply automatically. Server automation must set owner_id from APP_OWNER_USER_ID.
create extension if not exists pgcrypto;
create type public.confidence_level as enum ('VERIFIED_PUBLIC','HIGH','MEDIUM','LOW','REJECTED');
create type public.contact_source_type as enum ('JOB_POSTING_EXPLICIT','COMPANY_CAREERS_PAGE','COMPANY_CONTACT_PAGE','COMPANY_TEAM_PAGE','COMPANY_ABOUT_PAGE','COMPANY_SITE_MAILTO','COMPANY_SITE_VISIBLE_TEXT','GENERIC_HIRING_INBOX','FOUNDER_OFFICIAL_SITE','GITHUB_PUBLIC_PROFILE','INFERRED_EMAIL_PATTERN','UNKNOWN');
create type public.sequence_state as enum ('DISCOVERED','CONTACT_FOUND','DRAFT_READY','BLOCKED_NO_EVIDENCE','READY_TO_SEND','INITIAL_SENT','FOLLOWUP_ONE_DUE','FOLLOWUP_ONE_SENT','FOLLOWUP_TWO_DUE','FOLLOWUP_TWO_SENT','REPLIED','BOUNCED','OPTED_OUT','PAUSED','CLOSED');
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
-- Minimal profile creation deliberately ignores untrusted auth metadata.
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id) values (new.id) on conflict (id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create table public.job_sources (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null, source_url text not null, source_type text not null check (source_type in ('ATS','COMPANY','CURATED','MANUAL')), is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id, source_url));
create table public.companies (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null, domain text not null, careers_url text, status text not null default 'UNKNOWN' check (status in ('ACTIVE','INACTIVE','UNKNOWN')), is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id, domain));
create table public.jobs (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, company_id uuid not null references public.companies(id) on delete cascade, source_id uuid references public.job_sources(id) on delete set null, title text not null, application_url text not null, location_text text not null, remote_type text not null check (remote_type in ('REMOTE','HYBRID','ONSITE','UNKNOWN')), status text not null check (status in ('OPEN','CLOSED','EXPIRED','UNKNOWN')), dedup_hash text not null, fit_score int check (fit_score between 0 and 100), fit_confidence numeric check (fit_confidence between 0 and 1), is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id, dedup_hash));
create table public.contact_people (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, company_id uuid not null references public.companies(id) on delete cascade, full_name text, title text, source_url text, is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id, company_id, full_name, title));
create table public.email_candidates (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, company_id uuid not null references public.companies(id) on delete cascade, contact_person_id uuid references public.contact_people(id) on delete set null, email text not null, normalized_email text not null, is_generic_hiring_inbox boolean not null default false, status text not null check (status in ('DISCOVERED','VALIDATED','REJECTED','SUPPRESSED')), is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id, normalized_email));
create table public.contact_evidence (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, email_candidate_id uuid not null references public.email_candidates(id) on delete cascade, source_url text not null, source_type public.contact_source_type not null, evidence_text text not null, contact_name text, contact_title text, email text not null, company_domain text not null, email_domain text not null, domain_matches boolean not null, public_explicit boolean not null, confidence public.confidence_level not null, requires_human_review boolean not null default true, autosend_eligible boolean not null default false, rejection_reasons jsonb not null default '[]'::jsonb, is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id, email_candidate_id, source_url, email));
-- An eligible contact must retain explicit evidence, matching domains, and no review/rejection flags.
alter table public.contact_evidence add constraint contact_evidence_autosend_guard check (not autosend_eligible or (public_explicit and domain_matches and not requires_human_review and jsonb_array_length(rejection_reasons) = 0 and source_type not in ('INFERRED_EMAIL_PATTERN','GITHUB_PUBLIC_PROFILE','FOUNDER_OFFICIAL_SITE','UNKNOWN')));
create table public.outreach_sequences (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, job_id uuid not null references public.jobs(id) on delete cascade, email_candidate_id uuid not null references public.email_candidates(id) on delete cascade, state public.sequence_state not null default 'DISCOVERED', followup_count int not null default 0 check (followup_count between 0 and 2), next_followup_at timestamptz, paused boolean not null default false, is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id, job_id, email_candidate_id));
create table public.messages (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, sequence_id uuid not null references public.outreach_sequences(id) on delete cascade, direction text not null default 'OUTBOUND' check (direction in ('INBOUND','OUTBOUND')), kind text not null check (kind in ('INITIAL','FOLLOWUP_ONE','FOLLOWUP_TWO','REPLY','SYSTEM')), status text not null check (status in ('DRAFT','SENT','FAILED','CANCELLED')), subject text not null, body_text text not null, body_html text, sent_at timestamptz, is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(sequence_id, kind));
create table public.gmail_thread_references (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, sequence_id uuid not null references public.outreach_sequences(id) on delete cascade, gmail_message_id text not null, gmail_thread_id text not null, in_reply_to text, references_header text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id, gmail_message_id), unique(owner_id, gmail_thread_id, sequence_id));
create table public.workflow_runs (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, workflow_name text not null, status text not null check (status in ('QUEUED','RUNNING','SUCCEEDED','FAILED','SKIPPED')), dry_run boolean not null default true, started_at timestamptz not null default now(), completed_at timestamptz, summary text, is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.system_settings (id uuid primary key default gen_random_uuid(), owner_id uuid not null unique references auth.users(id) on delete cascade, timezone text not null default 'Asia/Kolkata', outreach_mode text not null default 'dry_run' check (outreach_mode = 'dry_run'), autosend_enabled boolean not null default false check (autosend_enabled = false), daily_send_limit int not null default 2 check (daily_send_limit between 0 and 100), min_fit_score int not null default 75 check (min_fit_score between 0 and 100), min_fit_confidence numeric not null default .85 check (min_fit_confidence between 0 and 1), min_contact_confidence numeric not null default .95 check (min_contact_confidence between 0 and 1), followup_interval_days int not null default 3 check (followup_interval_days = 3), max_followups int not null default 2 check (max_followups = 2), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.suppression_entries (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, email text, company_id uuid references public.companies(id) on delete cascade, role_key text, reason text not null check (reason in ('OPT_OUT','BOUNCE','MANUAL','RECENT_CONTACT','CLOSED_ROLE')), active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (email is not null or (company_id is not null and role_key is not null)), unique nulls not distinct(owner_id, email, company_id, role_key));
create table public.integration_events (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, integration text not null, event_type text not null, status text not null check (status in ('INFO','SUCCESS','FAILURE','BLOCKED')), dedup_hash text not null, detail jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id, integration, dedup_hash));
-- Owner indexes support both RLS filtering and common CRM views.
create index job_sources_owner_idx on public.job_sources(owner_id); create index companies_owner_idx on public.companies(owner_id); create index jobs_status_company_idx on public.jobs(owner_id, status, company_id); create index jobs_source_idx on public.jobs(source_id); create index contact_people_owner_company_idx on public.contact_people(owner_id, company_id); create index email_candidates_email_idx on public.email_candidates(owner_id, normalized_email); create index evidence_source_url_idx on public.contact_evidence(owner_id, source_url); create index outreach_sequences_owner_idx on public.outreach_sequences(owner_id); create index sequences_followup_idx on public.outreach_sequences(owner_id, next_followup_at) where not paused; create index messages_owner_direction_idx on public.messages(owner_id, direction, created_at desc); create index gmail_thread_idx on public.gmail_thread_references(owner_id, gmail_thread_id); create index workflow_runs_time_idx on public.workflow_runs(owner_id, started_at desc); create index settings_owner_idx on public.system_settings(owner_id); create index suppressions_owner_idx on public.suppression_entries(owner_id); create index integration_events_owner_idx on public.integration_events(owner_id, created_at desc);
alter table public.profiles enable row level security;
create policy user_reads_own_profile on public.profiles for select to authenticated using ((select auth.uid()) = id);
create policy user_updates_own_profile on public.profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
do $$ declare tbl text; begin foreach tbl in array array['job_sources','companies','jobs','contact_people','email_candidates','contact_evidence','outreach_sequences','messages','gmail_thread_references','workflow_runs','system_settings','suppression_entries','integration_events'] loop execute format('alter table public.%I enable row level security', tbl); execute format('create policy user_owns_rows on public.%I for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id)', tbl); end loop; end $$;
-- No anon policies exist. Server automation uses SUPABASE_SECRET_KEY and must write APP_OWNER_USER_ID explicitly.
do $$ declare tbl text; begin foreach tbl in array array['profiles','job_sources','companies','jobs','contact_people','email_candidates','contact_evidence','outreach_sequences','messages','gmail_thread_references','workflow_runs','system_settings','suppression_entries','integration_events'] loop execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()', tbl); end loop; end $$;
